{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a neutral lipophilic retinoid ester, has an absolute oral bioavailability of about 40% in healthy volunteers, supporting that a lipophilic retinoid amide such as the query can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a structurally related retinoid, has an absolute oral bioavailability of approximately 60% (range 36-95%) in healthy subjects, supporting high bioavailability for the retinoid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, which shares the same cyclohexene-polyene retinoid backbone as the query, has a systemic bioavailability of about 40%, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Even the lower reported estimate for oral all-trans retinoic acid bioavailability is 25-30%, still above the 20% threshold and supportive of high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide substructure with the query, has an absolute oral bioavailability of about 63%, supporting adequate absorption of the anilide motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "One report describes 13-cis retinoic acid as having low absolute bioavailability with significant gut degradation, providing some contradictory evidence, but it is not quantified below 20% and is outweighed by multiple retinoid bioavailability values above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a lipophilic retinoid amide. Multiple close retinoid analogs (etretinate ~40%, acitretin ~60%, isotretinoin ~40%, ATRA ~25-50%) and the paracetamol-like anilide moiety support oral bioavailability above the 20% threshold. Although some retinoid reports describe low or erratic absorption, none affirmatively establish F < 20%, so the balance favors high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself is provided.",
    "The contradictory 'low bioavailability' reports for retinoic acid isomers are not numerically tied to the 20% threshold.",
    "The effect of the amide bond and p-hydroxyaniline moiety on first-pass metabolism and absorption is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "retinoid ester"
    },
    {
      "applicability": "high",
      "card_ids": ["C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "retinoid acid"
    },
    {
      "applicability": "high",
      "card_ids": ["C46"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "retinoid acid isomer"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C23"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "p-hydroxyanilide"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C14"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "retinoid acid isomer"
    }
  ],
  "revision_action": "initial"
}

